import sys

def total_queens_brute(n):
    board = [[0] * n for _ in range(n)]
    count = 0

    def can_place(r, c):
        for i in range(r):
            if board[i][c]:
                return False
        for i in range(r):
            d = r - i
            if c - d >= 0 and board[i][c - d]:
                return False
            if c + d < n and board[i][c + d]:
                return False
        return True

    def backtrack(r):
        nonlocal count
        if r == n:
            count += 1
            return
        for c in range(n):
            if can_place(r, c):
                board[r][c] = 1
                backtrack(r + 1)
                board[r][c] = 0

    backtrack(0)
    return count

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(total_queens_brute(n))

import sys

def total_queens_best(n):
    count = 0

    def backtrack(r, cols, d1, d2):
        nonlocal count
        if r == n:
            count += 1
            return
        for c in range(n):
            if (cols >> c) & 1 or (d1 >> (r + c)) & 1 or (d2 >> (r - c + n - 1)) & 1:
                continue
            backtrack(r + 1, cols | (1 << c), d1 | (1 << (r + c)), d2 | (1 << (r - c + n - 1)))

    backtrack(0, 0, 0, 0)
    return count

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(total_queens_best(n))
